
.forum {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}

.forum-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--surface-2);
  border-bottom: 1px solid var(--border);
}

.forum-brand {
  display: flex;
  align-items: center;
  gap: 8px;
}

.forum-name {
  font-weight: 600;
  letter-spacing: 1px;
}

.forum-tag {
  font-size: 12px;
  color: var(--accent-2);
  border: 1px solid var(--accent-2);
  border-radius: 20px;
  padding: 2px 10px;
}

.icon {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: none;
}

.icon.logo {
  color: var(--accent);
}

.tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}

.tab {
  flex: 1;
  padding: 10px 0;
  font-size: 13px;
  color: var(--text-dim);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;

  &.active {
    color: var(--accent);
    border-bottom-color: var(--accent);
    font-weight: 600;
  }
}

.tab-count {
  margin-left: 4px;
  font-size: 11px;
}

.toolbar {
  display: flex;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  font-size: 13px;
  color: var(--text);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;

  &:hover:not(:disabled) {
    border-color: var(--accent);
    background: #1c2633;
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #0b1a2a;

  &:hover:not(:disabled) {
    background: #78b6ff;
    border-color: #78b6ff;
  }
}

.btn.ghost {
  background: transparent;
}

.btn.mini {
  padding: 4px 8px;
  font-size: 12px;
}

.post-list,
.reply-list,
.friend-list,
.chat-list {
  list-style: none;
}

.post-list,
.reply-list {
  padding: 0 16px;
}

.post-item {
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
  cursor: pointer;

  &:last-child {
    border-bottom: none;
  }

  &:hover .post-title {
    color: var(--accent);
  }
}

.post-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  word-break: break-word;
}

.post-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
  font-size: 12px;
  color: var(--text-dim);
}

.post-author {
  color: var(--accent);
}

.friend-hint {
  font-size: 12px;
  color: var(--text-dim);
}

.detail-view {
  padding-bottom: 16px;
}

.post-detail {
  padding: 16px;
  border-bottom: 1px solid var(--border);
}

.post-body,
.reply-body {
  margin-top: 12px;
  color: var(--text);
  white-space: pre-wrap;
  word-break: break-word;
}

.replies {
  padding: 0 16px;
}

.replies-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
}

.replies-head h3 {
  font-size: 14px;
  font-weight: 600;
}

.reply-item {
  padding: 12px 0;
  border-top: 1px solid var(--border);
}

.reply-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  color: var(--text-dim);
}

.reply-body {
  margin-top: 4px;
  font-size: 13px;
}

.detail-view > .btn.primary {
  margin: 12px 16px 0;
}

.friend-list {
  padding: 0 16px;
}

.friend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);

  &:last-child {
    border-bottom: none;
  }
}

.friend-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
}

.friend-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--accent);
}

.friend-preview {
  max-width: 100%;
  font-size: 12px;
  color: var(--text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chat-view {
  display: flex;
  flex-direction: column;
}

.chat-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
}

.chat-name {
  flex: 1;
  font-size: 14px;
  font-weight: 600;
}

.chat-list {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 120px;
}

.msg-row {
  display: flex;

  &.me {
    justify-content: flex-end;
  }

  &.other {
    justify-content: flex-start;
  }
}

.msg-bubble {
  max-width: 78%;
  padding: 8px 12px;
  border-radius: 10px;
  background: var(--surface-2);
  border: 1px solid var(--border);
}

.msg-row.me .msg-bubble {
  background: var(--accent);
  border-color: var(--accent);
  color: #0b1a2a;
}

.msg-author {
  display: block;
  font-size: 11px;
  color: var(--accent-2);
  margin-bottom: 2px;
}

.msg-text {
  font-size: 13px;
  white-space: pre-wrap;
  word-break: break-word;
}

.msg-time {
  display: block;
  margin-top: 4px;
  font-size: 10px;
  opacity: 0.7;
  text-align: right;
}

.composer {
  display: flex;
  gap: 8px;
  padding: 10px 16px;
  border-top: 1px solid var(--border);
}

.composer .input {
  flex: 1;
  margin-bottom: 0;
}

.empty {
  padding: 40px 20px;
  text-align: center;
  color: var(--text-dim);
}

.empty.small {
  padding: 20px;
}

.empty p {
  font-size: 14px;
}

.empty-sub {
  margin-top: 6px;
  font-size: 12px;
  color: var(--text-dim);
}

.modal {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(0, 0, 0, 0.6);
  z-index: 10;
}

.modal-card {
  width: 100%;
  max-width: 460px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
}

.modal-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 12px;
}

.input,
.textarea {
  width: 100%;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  padding: 9px 12px;
  font-family: inherit;
  font-size: 13px;
  resize: vertical;

  &:focus {
    outline: none;
    border-color: var(--accent);
  }
}

.input {
  margin-bottom: 10px;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 14px;
}
